# Order aggregate with OrderItem entities + in-memory repository
class OrderItem:
    def __init__(self, sku, quantity, unit_price_cents):
        self.sku = sku
        self.quantity = quantity
        self.unit_price_cents = unit_price_cents

    def subtotal(self):
        return self.quantity * self.unit_price_cents

class Order:   # Aggregate Root
    def __init__(self, order_id, customer_id):
        self.order_id = order_id
        self.customer_id = customer_id
        self._items = []
        self.status = 'draft'

    def add_item(self, sku, quantity, unit_price_cents):
        if self.status != 'draft':
            raise ValueError('Cannot add items to a confirmed order')
        self._items.append(OrderItem(sku, quantity, unit_price_cents))

    def confirm(self):
        if not self._items:
            raise ValueError('Cannot confirm empty order')
        self.status = 'confirmed'

    def total_cents(self):
        return sum(i.subtotal() for i in self._items)

class OrderRepository:
    def __init__(self):
        self._store = {}

    def save(self, order):
        self._store[order.order_id] = order

    def find_by_id(self, order_id):
        return self._store.get(order_id)

repo = OrderRepository()
o = Order('ORD-1', 'CUST-42')
o.add_item('SKU-A', 2, 1500)
o.add_item('SKU-B', 1, 3000)
o.confirm()
repo.save(o)

loaded = repo.find_by_id('ORD-1')
print(f'Order: {loaded.order_id}, status: {loaded.status}')
total = loaded.total_cents()
print(f'Total: {total // 100}.{total % 100:02d} USD')
